<?php
require_once __DIR__.'/../model/MedicalRecordModel.php';
class MedicalRecordController { private MedicalRecordModel $model; public function __construct(?PDO $pdo=null){$this->model=new MedicalRecordModel($pdo);} public function authorize():void{if(session_status()===PHP_SESSION_NONE)session_start();$roleId=(int)($_SESSION['role_id']??$_SESSION['role']??0);$role=strtolower((string)($_SESSION['role_name']??$_SESSION['role']??''));if($roleId!==11&&!str_contains($role,'clinic')){http_response_code(403);throw new RuntimeException('You are not authorized to view medical records.');}} public function getCsrfToken():string{if(session_status()===PHP_SESSION_NONE)session_start();return $_SESSION['clinic_medical_record_csrf']??=bin2hex(random_bytes(32));} public function getEmployees(string $search=''):array{return $this->model->searchEmployees(substr(trim($search),0,100));} public function getHistory(array $input):array{$id=$this->employeeId($input['employee_id']??null);$from=$this->date($input['date_from']??'');$to=$this->date($input['date_to']??'');if($from!==''&&$to!==''&&$from>$to)throw new InvalidArgumentException('The start date must be before the end date.');return['employee'=>$this->model->getEmployeeSummary($id),'history'=>$this->model->getHistory($id,$from,$to,max(1,(int)($input['page']??1)),10)];} public function getRecord(array $input):?array{return $this->model->getRecord($this->recordId($input['record_id']??null),$this->employeeId($input['employee_id']??null));} public function save(array $input,int $userId):array{$data=$this->validate($input);$patient=$this->model->getPatientForEmployee($data['employee_id']);if(!$patient)throw new InvalidArgumentException('The selected employee is not registered as an active clinic patient.');$data['patient_id']=$patient['patient_id'];$data['created_by']=$userId;$id=$this->model->createRecord($data);return $this->model->getRecord((string)$id,$data['employee_id'])??[];} public function update(array $input):array{$data=$this->validate($input);$id=$this->recordId($input['record_id']??null);if(!$this->model->updateRecord($id,$data['employee_id'],$data))throw new RuntimeException('Medical record not found.');return $this->model->getRecord($id,$data['employee_id'])??[];} public function delete(array $input):void{if(!$this->model->deleteRecord($this->recordId($input['record_id']??null),$this->employeeId($input['employee_id']??null)))throw new RuntimeException('Medical record not found.');} private function validate(array $input):array{$data=['employee_id'=>$this->employeeId($input['employee_id']??null)];foreach(['record_date','examination','chief_complaint'] as $field){$value=trim((string)($input[$field]??''));if($value==='')throw new InvalidArgumentException(ucwords(str_replace('_',' ',$field)).' is required.');$data[$field]=$field==='record_date'?$this->date($value):substr($value,0,5000);}foreach(['diagnosis','treatment','notes'] as $field)$data[$field]=substr(trim((string)($input[$field]??'')),0,5000)?:null;$v=[];foreach(['blood_pressure','heart_rate','temperature','respiratory_rate','weight','height'] as $field){$value=trim((string)($input[$field]??''));if($value!==''){if($field!=='blood_pressure'&&!is_numeric($value))throw new InvalidArgumentException('Vital sign values must be numeric.');$v[$field]=substr($value,0,30);}}$data['vital_signs']=$v?json_encode($v,JSON_THROW_ON_ERROR):null;$data['status']=trim((string)($input['status']??'Pending'));if(!in_array($data['status'],['Pending','Completed','Follow-up Required'],true))throw new InvalidArgumentException('Invalid medical record status.');return $data;} private function employeeId(mixed $value):int{$id=filter_var($value,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id===false)throw new InvalidArgumentException('A valid employee is required.');return $id;} private function recordId(mixed $value):string{$value=trim((string)$value);if($value===''||!ctype_digit($value)||strlen($value)>20)throw new InvalidArgumentException('A valid medical record is required.');return $value;} private function date(mixed $value):string{$value=trim((string)$value);if($value==='')return'';$date=DateTimeImmutable::createFromFormat('!Y-m-d',$value);if(!$date||$date->format('Y-m-d')!==$value)throw new InvalidArgumentException('Invalid date.');return$value;}}
